<summary>Assets/Scripts/UI/LiveOps/RewardScreen.cs (6)</summary><blockquote>

`369-379`: **Guard against missing `_screenCanvasGroup`.**

A missing reference will NRE here. Fail gracefully and log.

Apply this diff:

```diff
     public void HideThisScreen(bool hide, bool forceRaycastBlock = false)
     {
-        _screenCanvasGroup.alpha = hide ? 0 : 1;
-        _screenCanvasGroup.interactable = hide ? false : true;
+        if (_screenCanvasGroup == null)
+        {
+            Debug.LogWarning("RewardScreen: _screenCanvasGroup is not assigned.");
+            return;
+        }
+        _screenCanvasGroup.alpha = hide ? 0 : 1;
+        _screenCanvasGroup.interactable = !hide;
         if (forceRaycastBlock)
         {
             _screenCanvasGroup.blocksRaycasts = true;
             return;
         }
-        _screenCanvasGroup.blocksRaycasts = hide ? false : true;
+        _screenCanvasGroup.blocksRaycasts = !hide;
     }
```

---

`133-145`: **Grid sizing: avoid Screen.width/scale hacks; set GridLayout constraint explicitly and rebuild.**

Using `Screen.width` and scaling the layout rect breaks with CanvasScaler/safe areas. Prefer fixed column count and let the layout drive size.


Apply this diff:

```diff
     private void ResizeLayoutGroup(int rewardCount)
     {
-        if (rewardCount <= 9)
-        {
-            _rewardsLayoutRect.sizeDelta = new Vector2(Screen.width, _rewardsLayoutRect.sizeDelta.y);
-            _rewardsLayoutRect.localScale = Vector3.one;
-            _gridLayoutGroup.constraintCount = 3;
-        }
-        else 
-        {
-            _rewardsLayoutRect.localScale = Vector3.one * 0.8f;
-            _gridLayoutGroup.constraintCount = 4;
-        }
+        _gridLayoutGroup.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
+        if (rewardCount <= 9)
+            _gridLayoutGroup.constraintCount = 3;
+        else
+            _gridLayoutGroup.constraintCount = 4;
+        LayoutRebuilder.ForceRebuildLayoutImmediate(_rewardsLayoutRect);
         // SFX
-        if (_rewardScreenOpenSound != null)
-            AudioManager.Instance.PlayClip(_rewardScreenOpenSound);
+        // Consider not replaying open SFX here to avoid double sound with initial show.

         _canTap = false;
         StartCoroutine(EnableTapAfterDelay(2.5f));
```


